// How we would attack a sender (tools/sonar/attacks.py): Forge sends a lie in FORMATS[format]'s layout (encode);
// Garbage sends any value with (v & mask) == value (it passes the team's check, meaning unknown); Random sends random
// values (class 0, every team we can't read); Silent teams hear nothing of ours. One value reaches every Forge or
// Garbage class whose check it passes, so a spoofer picks the value passing the most classes its lock implies.
enum class AttackKind { Random, Forge, Garbage, Silent };
struct Attack {
    AttackKind kind = AttackKind::Random;
    int format = -1;
    std::uint64_t mask = 0, value = 0;
};
